function updateForge(dt,ctx,c,d){d.pos+=d.dir*d.speed*dt;if(d.pos>=1){d.pos=1;d.dir=-1}else if(d.pos<=0){d.pos=0;d.dir=1}const x0=90,x1=c.width-90,y=c.height/2,w=x1-x0;ctx.fillStyle="#1a2536";ctx.fillRect(x0,y-25,w,50);ctx.fillStyle="#873c3c";ctx.fillRect(x0,y-25,w*.18,50);ctx.fillRect(x1-w*.18,y-25,w*.18,50);ctx.fillStyle="#4a7b55";ctx.fillRect(x0+w*.18,y-25,w*.22,50);ctx.fillRect(x1-w*.40,y-25,w*.22,50);ctx.fillStyle="#d7aa45";ctx.fillRect(x0+w*.40,y-25,w*.20,50);const px=x0+w*d.pos;ctx.fillStyle="#fff";ctx.shadowBlur=15;ctx.shadowColor="#fff0a0";ctx.fillRect(px-3,y-42,6,84);ctx.shadowBlur=0;ctx.fillStyle="#ccecff";ctx.font="700 17px Arial";ctx.textAlign="center";ctx.fillText(`${d.strikes.length}/3`,c.width/2,y+88);const el=miniEls();el.score.textContent=`${d.strikes.join(" • ")||"READY"} • ${d.time.toFixed(1)}s`}
function updateSlots(dt,ctx,c,d){d.spin+=dt*9;const arrays=[d.enemy,d.player,d.reward];const labels=["ENEMY","PLAYER","REWARD"];for(let i=0;i<3;i++){const x=75+i*255,y=120,w=210,h=210;ctx.fillStyle="rgba(15,30,50,.94)";ctx.strokeStyle=i===d.reel?"#ff82d7":"#34506d";ctx.lineWidth=3;ctx.fillRect(x,y,w,h);ctx.strokeRect(x,y,w,h);const val=d.stopped[i]||arrays[i][Math.floor(d.spin+i*1.7)%arrays[i].length];ctx.fillStyle="#7a98b6";ctx.font="700 12px Arial";ctx.textAlign="center";ctx.fillText(labels[i],x+w/2,y+34);ctx.fillStyle="#f4fbff";ctx.font="900 19px Arial";wrapText(ctx,val,x+w/2,y+112,w-24,24)}const el=miniEls();el.score.textContent=`${VSX.lang==="vi"?"DỪNG":"STOPPED"} ${d.stopped.length}/3 • ${d.time.toFixed(1)}s`}
function wrapText(ctx,text,x,y,maxW,lineH){const words=String(text).split(" ");let line="",yy=y;for(const word of words){const test=line?line+" "+word:word;if(ctx.measureText(test).width>maxW&&line){ctx.fillText(line,x,yy);line=word;yy+=lineH}else line=test}if(line)ctx.fillText(line,x,yy)}
function miniAction(code,repeat=false){if(!MINI.active)return;if(code==="Escape"){endMiniEvent(false,{reason:"user-abort"});return}if(repeat&&code==="Space")return;if(MINI.id==="weapon_forge"&&code==="Space"){const p=MINI.data.pos,dist=Math.abs(p-.5),q=dist<.07?"PERFECT":dist<.20?"GOOD":"BAD";MINI.data.strikes.push(q);MINI.data.speed*=1.13;if(MINI.data.strikes.length>=3)endMiniEvent(true,{reason:"forge-complete"})}else if(MINI.id==="slot_machine_doom"&&code==="Space"){const d=MINI.data;if(d.stopped.length<3){const arr=d.stopped.length===0?d.enemy:d.stopped.length===1?d.player:d.reward;d.stopped.push(arr[Math.floor(d.spin+d.stopped.length*1.7)%arr.length]);d.reel=d.stopped.length;if(d.stopped.length>=3)setTimeout(()=>{if(MINI.active)slotToChallenge()},450)}}}
document.addEventListener("keydown",function(ev){if(game.state!=="EVENT_MINIGAME")return;ev.preventDefault();ev.stopImmediatePropagation();MINI.keys.add(ev.code);miniAction(ev.code,ev.repeat)},true);
document.addEventListener("keyup",function(ev){if(game.state==="EVENT_MINIGAME"){MINI.keys.delete(ev.code);ev.preventDefault();ev.stopImmediatePropagation()}},true);
// ---------- Render: world markers, polarity/team readability and minimap overlay ----------
const ADV_RENDER_BASE=Game.prototype.render;
Game.prototype.render=function(){if(this.state==="EVENT_BRIEFING"&&this.worldEvent){const held=this.worldEvent;this.worldEvent=null;try{return ADV_RENDER_BASE.call(this)}finally{this.worldEvent=held}}const r=ADV_RENDER_BASE.call(this);if(!this.player||this.state==="TITLE")return r;ctx.save();ctx.translate(-this.camera.x,-this.camera.y);for(const o of this.vsxAdvancedEventObjects||[])if(!o.dead)o.render(ctx);const ev=this.worldEvent;if(ev?.id==="hot_potato_core"){const x=ev.carrier==="enemy"&&ev.carrierEnemy&&!ev.carrierEnemy.dead?ev.carrierEnemy.x:this.player.x,y=ev.carrier==="enemy"&&ev.carrierEnemy&&!ev.carrierEnemy.dead?ev.carrierEnemy.y:this.player.y;ctx.strokeStyle=ev.fuse<2.3?"#ff385e":"#ff9b62";ctx.lineWidth=4;ctx.shadowBlur=15;ctx.shadowColor=ctx.strokeStyle;ctx.beginPath();ctx.arc(x,y,19+5*Math.sin(this.time*9),0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle="#fff1cf";ctx.font="900 9px Arial";ctx.textAlign="center";ctx.fillText(ev.fuse.toFixed(1),x,y-28)}else if(ev?.id==="polarity_crisis"){for(const e of this.enemies){if(e.dead||!e.vsxPolarity)continue;ctx.fillStyle=e.vsxPolarity>0?"#65ddff":"#ff77c6";ctx.font="900 10px Arial";ctx.textAlign="center";ctx.fillText(e.vsxPolarity>0?"+":"−",e.x,e.y-e.size-9)}}else if(ev?.id==="enemy_civil_war"){for(const e of this.enemies){if(e.dead||!e.vsxWarTeam)continue;ctx.strokeStyle=e.vsxWarTeam===1?"rgba(255,75,98,.65)":"rgba(80,145,255,.65)";ctx.lineWidth=e.vsxWarCaptain?4:2;ctx.beginPath();ctx.arc(e.x,e.y,e.size+5,0,Math.PI*2);ctx.stroke()}}else if(ev?.id==="shrinking_jackpot"){ctx.fillStyle="rgba(255,208,78,.08)";ctx.strokeStyle="#ffd361";ctx.lineWidth=4;ctx.beginPath();ctx.arc(ev.cx,ev.cy,ev.radius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle="#ffe8a0";ctx.font="900 12px Arial";ctx.textAlign="center";ctx.fillText(`JACKPOT x${ev.tier}`,ev.cx,ev.cy-ev.radius-10)}ctx.restore();renderAdvancedMinimap(this);return r};
function mapMarkerList(g){const ev=g.worldEvent,out=[];if(VSX?.save?.settings?.minimapLayerObjectives===false)return out;if(!ev)return out;const d=ADV_EVENT_DEFS[ev.id];if(!d)return out;if(ev.id==="hot_potato_core"){const target=ev.carrier==="enemy"&&ev.carrierEnemy&&!ev.carrierEnemy.dead?ev.carrierEnemy:g.player;out.push({x:target.x,y:target.y,label:"H",color:d.color})}else if(ev.id==="polarity_crisis")out.push({x:g.player.x,y:g.player.y,label:ev.polarity>0?"+":"-",color:ev.polarity>0?"#65ddff":"#ff77c6"});else if(ev.id==="treasure_stampede"){for(const e of g.enemies.filter(x=>x.isTreasureDrone&&!x.dead).slice(0,8))out.push({x:e.x,y:e.y,label:"$",color:d.color})}else if(ev.id==="chaos_contract"||ev.id==="quantum_draft"){for(const o of g.vsxAdvancedEventObjects||[])if(!o.dead)out.push({x:o.x,y:o.y,label:o.label,color:o.color})}else if(ev.id==="enemy_civil_war"){for(const e of g.enemies.filter(x=>x.vsxWarCaptain&&!x.dead))out.push({x:e.x,y:e.y,label:e.vsxWarTeam===1?"R":"B",color:e.vsxWarTeam===1?"#ff536a":"#5d9cff"})}else if(ev.id==="shrinking_jackpot")out.push({x:ev.cx,y:ev.cy,label:"J",color:d.color,ring:ev.radius});return out}
function directorMapStatus(g){
 const ds=window.VSX_ENCOUNTER_DIRECTOR?.state?.(),L=(en,vi)=>VSX.lang==='vi'?vi:en;
 if(g.vsxPendingEventBriefing||g.state==='EVENT_BRIEFING')return{color:'#7deaff',text:L('ENCOUNTER BRIEFING · COUNTDOWN PAUSED','BRIEFING ENCOUNTER · ĐÃ DỪNG ĐẾM')};
 if(g.worldEvent){const t=Number(g.worldEvent.time);return{color:'#ffcf8d',text:`${L('WORLD EVENT ACTIVE','WORLD EVENT ĐANG CHẠY')}${Number.isFinite(t)?` · ${Math.max(0,Math.ceil(t))}s`:''}`}}
 const ms=window.VSX_MINIGAME_SYSTEM?.state?.(),relay=window.VSX_VOID_RELAY_SERIES;
 if(ms?.active||relay?.active||window.VSX_TRIAL?.active||g.state==='EVENT_MINIGAME'||g.state==='VSX_MINIGAME'||g.state==='VSX_RELAY_MINIGAME'||g.state==='MINIGAME'){
   let t=ms?.time??relay?.data?.time??window.VSX_VOID_RELAY_SERIES?.state?.()?.time??window.VSX?.eventDebug?.mini?.data?.time??null;if(!Number.isFinite(Number(t)))t=null;
   return{color:'#c78cff',text:`${L('MINIGAME ACTIVE','MINIGAME ĐANG CHẠY')}${t!=null?` · ${Math.max(0,Math.ceil(Number(t)))}s`:''}`}
 }
 const na=window.VSX_NOVEL_ALLIES?.state?.(),fa=window.VSX_FINAL8_ALLIES?.state?.();
 if(g.activeRecruitChallenge||na?.active||fa?.active){const d=na?.data||fa?.data||null,t=Number(d?.time);return{color:'#78e7c0',text:`${L('ALLY ENCOUNTER ACTIVE','ENCOUNTER ALLY ĐANG CHẠY')}${Number.isFinite(t)?` · ${Math.max(0,Math.ceil(t))}s`:''}`}}
 if(g.boss&&!g.boss.dead||g.miniBoss&&!g.miniBoss.dead)return{color:'#ff839a',text:L('MAJOR ENCOUNTER ACTIVE · DIRECTOR PAUSED','ENCOUNTER LỚN ĐANG CHẠY · DIRECTOR TẠM DỪNG')};
 if(ds?.active)return{color:'#7deaff',text:`${L('ENCOUNTER STARTING','ĐANG KHỞI TẠO ENCOUNTER')} · ${String(ds.active.category||'').toUpperCase()}`};
 if(ds?.enabled){const cd=Math.max(0,Number(ds.nextIn)||0);return{color:cd<=0?'#ffd27a':'#7194b1',text:cd<=0?L('ENCOUNTER READY','TÍN HIỆU SẴN SÀNG'):`${L('Next encounter','Tín hiệu kế tiếp')} ${Math.ceil(cd)}s`}}
 const cd=Math.max(0,Number(g.vsxWorldCooldown??30));return{color:g.vsxEventReady?'#ffd27a':'#7194b1',text:g.vsxEventReady?L('ENCOUNTER READY','TÍN HIỆU SẴN SÀNG'):`${L('Next encounter','Tín hiệu kế tiếp')} ${Math.ceil(cd)}s`}
}
window.VSX_REFRESH_ENCOUNTER_MAP_STATUS=function(){try{const meta=document.getElementById('vsxMinimapMeta');if(!meta||!game?.player)return false;const st=directorMapStatus(game),parts=String(meta.innerHTML||'').split(/<br\s*\/?\s*>/i);if(!parts.length)parts.push('');parts[0]=`<span style="color:${st.color}">${VSX.esc(st.text)}</span>`;meta.innerHTML=parts.join('<br>');return true}catch(err){console.warn('[VSX MAP STATUS SYNC]',err);return false}};
function renderAdvancedMinimap(g){
 const cvs=document.getElementById("vsxMinimapCanvas"),meta=document.getElementById("vsxMinimapMeta"),legend=document.getElementById("vsxMinimapLegend"),wrap=document.getElementById("vsxMinimapWrap");if(!cvs||!meta||!legend||!wrap||wrap.style.display==="none")return;const frame=wrap.dataset.vsxMapFrame||'0';if(wrap.dataset.vsxAdvancedFrame===frame)return;wrap.dataset.vsxAdvancedFrame=frame;const mctx=cvs.getContext("2d"),ev=g.worldEvent,d=ev&&ADV_EVENT_DEFS[ev.id],w=cvs.width,h=cvs.height,cx=w/2,cy=h/2,maxR=Math.min(w,h)/2-14,R=1250,baseMeta=wrap.dataset.vsxBaseMeta||meta.innerHTML||'';
 function proj(x,y){let dx=x-g.player.x,dy=y-g.player.y,sx=dx/R*maxR,sy=dy/R*maxR,dd=Math.hypot(sx,sy);if(dd>maxR){const k=maxR/dd;sx*=k;sy*=k}return{x:cx+sx,y:cy+sy}}
 if(d){const list=mapMarkerList(g);for(const m of list){const p=proj(m.x,m.y);mctx.save();mctx.fillStyle=m.color;mctx.strokeStyle="#fff";mctx.shadowBlur=12;mctx.shadowColor=m.color;mctx.lineWidth=1.2;mctx.beginPath();mctx.arc(p.x,p.y,5,0,Math.PI*2);mctx.fill();mctx.stroke();mctx.shadowBlur=0;mctx.fillStyle="#fff";mctx.font="900 8px Arial";mctx.textAlign="center";mctx.fillText(m.label,p.x,p.y-9);if(m.ring){mctx.strokeStyle="rgba(255,211,97,.6)";mctx.lineWidth=1.5;mctx.beginPath();mctx.arc(p.x,p.y,Math.max(4,m.ring/R*maxR),0,Math.PI*2);mctx.stroke()}mctx.restore()}mctx.save();mctx.strokeStyle=d.color;mctx.globalAlpha=.85;mctx.lineWidth=2.5;mctx.strokeRect(5,5,w-10,h-10);mctx.restore();const objective=eventStatus(g,ev);{const html=`<span style="color:${d.color}"><b>${d.icon}</b> ${VSX.esc(d.name[VSX.lang])} • ${VSX.esc(objective)}</span><br>${baseMeta}`;if(meta.innerHTML!==html)meta.innerHTML=html;}if(!document.getElementById("vsxAdvEventLegend")){const s=document.createElement("span");s.id="vsxAdvEventLegend";s.className="vsxMapChip";legend.appendChild(s)}const l=document.getElementById("vsxAdvEventLegend");l.innerHTML=`<i class="vsxMapDot triangle" style="color:${d.color}"></i>${d.icon} ${VSX.lang==="vi"?"Mục tiêu sự kiện":"Event objective"}`;l.style.display="inline-flex"}
 else{const l=document.getElementById("vsxAdvEventLegend");if(l)l.style.display="none";const st=directorMapStatus(g),html=`<span style="color:${st.color}">${VSX.esc(st.text)}</span><br>${baseMeta}`;if(meta.innerHTML!==html)meta.innerHTML=html}
}
function eventStatus(g,ev){const id=ev.id;if(id==="hot_potato_core")return `${ev.carrier==="player"?(VSX.lang==="vi"?"TRÊN NGƯỜI CHƠI":"ON PLAYER"):(VSX.lang==="vi"?"TRÊN KẺ ĐỊCH":"ON ENEMY")} • ${ev.fuse.toFixed(1)}s`;if(id==="polarity_crisis")return `${ev.polarity>0?"+":"-"} • ${VSX.lang==="vi"?"E đổi cực":"E flips polarity"} • ${ev.deflects||0} ${VSX.lang==="vi"?"đạn đẩy":"deflects"}`;if(id==="treasure_stampede")return `${ev.dronesKilled||0}/6 ${VSX.lang==="vi"?"drone hạ":"drones down"}`;if(id==="chaos_contract")return ev.phase==="choose"?(VSX.lang==="vi"?"Chọn C1 / C2 / C3":"Choose C1 / C2 / C3"):`${ev.contract} • ${Math.ceil(ev.time)}s`;if(id==="enemy_civil_war")return `${VSX.lang==="vi"?"Hạ bởi phe đối địch":"Faction kills"} ${ev.chaosScore||0}`;if(id==="quantum_draft")return ev.phase==="choose"?(VSX.lang==="vi"?"W Vũ khí • P Nội tại • M Đột biến":"W Weapon • P Passive • M Mutation"):`${ev.choice} • ${Math.ceil(ev.time)}s`;if(id==="shrinking_jackpot")return `x${ev.tier} • ${Math.ceil(ev.time)}s`;if(id==="slot_machine_doom"&&ev.phase==="challenge")return `${ev.enemyMod} • ${ev.playerMod} -> ${ev.slotReward}`;return `${Math.ceil(ev.time||0)}s`}
const ADV_HUD_BASE=Game.prototype.updateHUD;
Game.prototype.updateHUD=function(force=false){if(this.state==="EVENT_BRIEFING"&&this.worldEvent){const held=this.worldEvent;this.worldEvent=null;let rr;try{rr=ADV_HUD_BASE.call(this,force)}finally{this.worldEvent=held}const ee=document.getElementById("vsxEventHud");if(ee)ee.style.display="none";return rr}const r=ADV_HUD_BASE.call(this,force);const eh=document.getElementById("vsxEventHud"),ev=this.worldEvent;if(!eh)return r;if(ev&&ADV_EVENT_DEFS[ev.id]){const d=ADV_EVENT_DEFS[ev.id],pct=100*clamp((ev.time||0)/(ev.max||d.duration||1),0,1);eh.style.display="block";eh.style.borderColor=d.color;eh.style.boxShadow=`0 8px 28px rgba(0,0,0,.28),0 0 18px ${d.color}22`;eh.innerHTML=`<div class="vsxEvtTop"><span class="vsxEvtGlyph" style="background:${d.color};color:#07111d">${VSX.esc(d.icon)}</span>${typeLabel(d)}</div><div class="vsxEvtName">${VSX.esc(d.name[VSX.lang])}</div><div class="vsxEvtStatus"><b>${VSX.lang==="vi"?"MỤC TIÊU":"OBJECTIVE"}</b> ${VSX.esc(eventStatus(this,ev))}</div><div class="vsxEvtProgress"><i style="width:${pct}%;background:${d.color};color:${d.color}"></i></div>`}else if(!ev&&this.vsxEventReady){eh.style.display="block";eh.style.borderColor="#d69a54";eh.innerHTML=`<div class="vsxEvtTop">ANOMALY</div><div class="vsxEvtName">${VSX.lang==="vi"?"SỰ KIỆN ĐÃ SẴN SÀNG":"EVENT READY"}</div><div class="vsxEvtStatus">${VSX.lang==="vi"?"Sẵn sàng triển khai ngay khi overlay hiện tại đóng":"Ready to deploy when the current overlay closes"}</div>`}return r};
