VSX.advancedEventIds=ADV_IDS;VSX.startWorldEventId=(id,forced=false)=>startWorldEventId(game,id,forced);VSX.startEventMinigame=(id)=>startEventMinigame(id);VSX.eventSchedulerState=()=>{const ds=window.VSX_ENCOUNTER_DIRECTOR?.state?.();const directorOn=!!ds?.enabled,active=game.worldEvent?.id||ds?.active?.id||null,isActive=!!(active||window.VSX_MINIGAME_SYSTEM?.state?.().active||window.VSX_VOID_RELAY_SERIES?.active||game.activeRecruitChallenge);const cooldown=directorOn?(isActive?null:Math.max(0,Number(ds.nextIn)||0)):game.vsxWorldCooldown;return{cooldown,ready:directorOn?!isActive&&cooldown<=0:game.vsxEventReady,active,state:game.state,director:directorOn,phase:directorOn?ds.phase:null,category:directorOn?(ds.active?.category||ds.lastCategory||null):null}};VSX.eventDebug={cleanup:()=>cleanupAdvanced(game),finish:(prev,reason)=>finishAdvanced(game,prev,reason),mini:MINI,endMini:endMiniEvent,slotToChallenge,stepMini:(dt=.016)=>{if(!MINI.active)return;const e=miniEls(),d=MINI.data;drawMiniBackground(e.ctx,e.canvas.width,e.canvas.height);if(MINI.id==="void_pinball")updatePinball(dt,e.ctx,e.canvas,d);else if(MINI.id==="weapon_forge")updateForge(dt,e.ctx,e.canvas,d);else updateSlots(dt,e.ctx,e.canvas,d)}};
